using System.IO;
using System.Net;
using System.Net.Http;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace ConsoleLauncher;
public sealed class NativeDetails:Grid,IDisposable{
 static readonly HttpClient Http=new(){Timeout=TimeSpan.FromSeconds(20)};
 static readonly SemaphoreSlim Images=new(3);
 readonly CancellationTokenSource cancel=new();readonly StackPanel body=new();readonly Grid viewer=new(){Background=Brushes.Black,Visibility=Visibility.Collapsed};readonly Image full=new(){Stretch=Stretch.Uniform};readonly MediaElement movie=new(){LoadedBehavior=MediaState.Manual,UnloadedBehavior=MediaState.Stop};readonly List<string> shots=new();int index,imageVersion;bool disposed,loaded,paused;
 static string Str(JsonElement e,string k)=>e.TryGetProperty(k,out var p)&&p.ValueKind==JsonValueKind.String?p.GetString()??"":"";
 static string Plain(string s)=>WebUtility.HtmlDecode(Regex.Replace(Regex.Replace(s,@"<(br\s*/?|/p|/li|/div)>","\n",RegexOptions.IgnoreCase),"<[^>]+>",""));
 static bool Safe(string s)=>Uri.TryCreate(s,UriKind.Absolute,out var u)&&u.Scheme=="https"&&(u.Host.EndsWith(".steamstatic.com",StringComparison.OrdinalIgnoreCase)||u.Host.EndsWith(".akamaihd.net",StringComparison.OrdinalIgnoreCase));
 public NativeDetails(Game game,Action launch,Func<Task> store,Action back){
  Background=new SolidColorBrush(Color.FromRgb(11,16,24));RowDefinitions.Add(new(){Height=GridLength.Auto});RowDefinitions.Add(new(){Height=new GridLength(1,GridUnitType.Star)});
  var top=new WrapPanel();Children.Add(top);top.Children.Add(Btn("Назад",back));top.Children.Add(Btn(game.Installed?"Играть":"Установить",launch));top.Children.Add(Btn("Купить / Steam",async()=>await store()));top.Children.Add(Btn("Звук и движение",()=>Experience.Settings(Window.GetWindow(this))));
  var scroll=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(scroll,1);Children.Add(scroll);Text(game.Name,42);Text(game.State+" · STEAM",14);var loading=Text("Загрузка описания…",18);
  Grid.SetRowSpan(viewer,2);Children.Add(viewer);viewer.RowDefinitions.Add(new(){Height=new GridLength(1,GridUnitType.Star)});viewer.RowDefinitions.Add(new(){Height=GridLength.Auto});viewer.Children.Add(full);viewer.Children.Add(movie);movie.Visibility=Visibility.Collapsed;
  var controls=new WrapPanel{Margin=new Thickness(16)};Grid.SetRow(controls,1);viewer.Children.Add(controls);controls.Children.Add(Btn("Закрыть просмотр",()=>HandleBack()));controls.Children.Add(Btn("Предыдущий",()=>Step(-1)));controls.Children.Add(Btn("Следующий",()=>Step(1)));controls.Children.Add(Btn("Пауза / продолжить",()=>{if(movie.Visibility!=Visibility.Visible)return;if(paused)movie.Play();else movie.Pause();paused=!paused;}));movie.MediaFailed+=(_,_)=>{movie.Stop();movie.Visibility=Visibility.Collapsed;};
  Loaded+=async(_,_)=>{if(loaded)return;loaded=true;await Load(game,loading);};Unloaded+=(_,_)=>movie.Stop();
 }
 static Button Btn(string text,Action action)=>NativeButton(text,action);
 static Button NativeButton(string text,Action action){var b=new Button{Content=text,FontSize=16,Padding=new Thickness(18,12,18,12),Margin=new Thickness(0,0,12,12),Foreground=Brushes.White,Background=new SolidColorBrush(Color.FromRgb(32,47,69))};b.Click+=(_,_)=>{Experience.Play("confirm");action();};return b;}
 TextBlock Text(string s,int size=18){var t=new TextBlock{Text=s,FontSize=size,Foreground=Brushes.White,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,14)};body.Children.Add(t);return t;}
 async Task<JsonDocument> Data(string key,string url,int minutes){var folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SteamConsoleLauncher","content");Directory.CreateDirectory(folder);var path=Path.Combine(folder,key+".json");if(File.Exists(path)&&DateTime.UtcNow-File.GetLastWriteTimeUtc(path)<TimeSpan.FromMinutes(minutes))try{return JsonDocument.Parse(await File.ReadAllTextAsync(path,cancel.Token));}catch(JsonException){}try{var json=await Http.GetStringAsync(url,cancel.Token);var doc=JsonDocument.Parse(json);try{await File.WriteAllTextAsync(path,json,cancel.Token);}catch{}return doc;}catch{if(File.Exists(path))return JsonDocument.Parse(await File.ReadAllTextAsync(path,cancel.Token));throw;}}
 async Task Load(Game game,TextBlock loading){try{using var doc=await Data(game.Id+"_ru","https://store.steampowered.com/api/appdetails?appids="+game.Id+"&l=russian",1440);if(disposed)return;var entry=doc.RootElement.GetProperty(game.Id);if(!entry.GetProperty("success").GetBoolean())throw new Exception();var data=entry.GetProperty("data");loading.Visibility=Visibility.Collapsed;Text(Plain(Str(data,"short_description")),22);var facts=new List<string>();foreach(var key in new[]{"developers","publishers"})if(data.TryGetProperty(key,out var list))facts.Add(string.Join(", ",list.EnumerateArray().Select(x=>x.GetString())));if(data.TryGetProperty("release_date",out var date))facts.Add(Str(date,"date"));if(data.TryGetProperty("genres",out var genres))facts.Add(string.Join(" · ",genres.EnumerateArray().Select(x=>Str(x,"description"))));Text(string.Join(" · ",facts),14);
  Text("Скриншоты",26);var thumbs=new WrapPanel();body.Children.Add(thumbs);if(data.TryGetProperty("screenshots",out var screenshots))foreach(var shot in screenshots.EnumerateArray()){var url=Str(shot,"path_full");if(!Safe(url))continue;int at=shots.Count;shots.Add(url);var image=new Image{Width=240,Height=135,Stretch=Stretch.UniformToFill};var b=Btn("",()=>OpenShot(at));b.Content=image;thumbs.Children.Add(b);_=Picture(image,Str(shot,"path_thumbnail"));}if(shots.Count==0)Text("Скриншоты недоступны.",16);
  Text("Видео",26);int count=0;if(data.TryGetProperty("movies",out var movies))foreach(var m in movies.EnumerateArray()){if(!m.TryGetProperty("mp4",out var mp4))continue;var url=Str(mp4,"480");if(url.Length==0)url=Str(mp4,"max");if(!Safe(url))continue;count++;string source=url;var b=Btn(Str(m,"name") is {Length:>0} n?n:"Смотреть трейлер",()=>{full.Visibility=Visibility.Collapsed;movie.Visibility=Visibility.Visible;viewer.Visibility=Visibility.Visible;movie.Volume=Experience.Volume;movie.Source=new Uri(source);paused=false;movie.Play();viewer.MoveFocus(new(System.Windows.Input.FocusNavigationDirection.First));});body.Children.Add(b);}if(count==0)Text("Прямой MP4-трейлер недоступен. HLS/DASH пока не поддерживаются.",16);Text("Об игре",26);Text(Plain(Str(data,"detailed_description")));
 }catch(OperationCanceledException){return;}catch{if(!disposed)loading.Text="Описание и медиа сейчас недоступны. Запуск игры от них не зависит.";}if(!disposed)await Reviews(game.Id);}
 async Task Reviews(string id){Text("Отзывы Steam",26);var note=Text("До 10 полезных отзывов · русский язык · все способы приобретения",14);try{var input=JsonSerializer.Serialize(new{appid=uint.Parse(id),filter=0,languages=new[]{"russian"},num_per_page=10,purchase_type=1,display_language="russian"});using var doc=await Data(id+"_reviews_ru","https://api.steampowered.com/IUserReviewsService/GetAppReviews/v1/?input_json="+Uri.EscapeDataString(input),10);if(disposed)return;var root=doc.RootElement;if(root.TryGetProperty("response",out var response))root=response;if(!root.TryGetProperty("reviews",out var reviews)||reviews.GetArrayLength()==0){note.Text="Для выбранного языка отзывы не найдены или источник не вернул список.";return;}foreach(var r in reviews.EnumerateArray()){Text(r.TryGetProperty("voted_up",out var up)&&up.GetBoolean()?"Рекомендует":"Не рекомендует",16);var s=Str(r,"review");Text(s.Length>4000?s[..4000]+"…":s,17);}}catch{if(!disposed)note.Text="Отзывы сейчас недоступны. Остальная карточка продолжает работать.";}}
 async Task Picture(Image image,string url,int version=-1){if(!Safe(url))return;try{await Images.WaitAsync(cancel.Token);try{var bytes=await Http.GetByteArrayAsync(url,cancel.Token);var result=await Task.Run(()=>{using var stream=new MemoryStream(bytes);var b=new BitmapImage();b.BeginInit();b.CacheOption=BitmapCacheOption.OnLoad;b.DecodePixelWidth=1600;b.StreamSource=stream;b.EndInit();b.Freeze();return b;});if(!disposed&&(version<0||version==imageVersion))image.Source=result;}finally{Images.Release();}}catch{}}
 void OpenShot(int at){if(shots.Count==0)return;index=(at+shots.Count)%shots.Count;movie.Stop();movie.Visibility=Visibility.Collapsed;full.Visibility=Visibility.Visible;viewer.Visibility=Visibility.Visible;full.Source=null;_=Picture(full,shots[index],++imageVersion);Experience.Transition(viewer);viewer.MoveFocus(new(System.Windows.Input.FocusNavigationDirection.First));}
 void Step(int delta){if(movie.Visibility!=Visibility.Visible)OpenShot(index+delta);}
 public bool HandleBack(){if(viewer.Visibility!=Visibility.Visible)return false;movie.Stop();viewer.Visibility=Visibility.Collapsed;Experience.Play("back");return true;}
 public void Dispose(){if(disposed)return;disposed=true;cancel.Cancel();movie.Stop();}
}
